      "QUERY": " SELECT BI.BIBID,BI.CUSTOMERID FROM BIBSEARCH BI WITH (NOLOCK) INNER JOIN BIBLIOGRAPHIC WITH (NOLOCK) ON BI.BIBID = BIBLIOGRAPHIC.BIBID AND BI.CUSTOMERID = BIBLIOGRAPHIC.CUSTOMERID INNER JOIN MATERIALS WITH (NOLOCK) ON MATERIALS.MATERIALTYPE = BI.MATERIALTYPE AND MATERIALS.CUSTOMERID = BI.CUSTOMERID   LEFT JOIN ( select [BIBID],[TAG],[SUBTAG],[INFO],[REL],[INFO_NOSIGN],[CUSTOMERID] COLLATE Latin1_General_CI_AS AS [CUSTOMERID] from Marc21Index245 where INFO like N'%tham vấn tâm lý cá nhân%' ) as MAR21INDEX_602 on MAR21INDEX_602.BIBID = BI.BIBID and MAR21INDEX_602.CUSTOMERID COLLATE Latin1_General_CI_AS = BI.CUSTOMERID WHERE BI.CUSTOMERID = 'DHHUE' AND (( ( MAR21INDEX_602.CUSTOMERID = 'DHHUE' AND (MAR21INDEX_602.INFO like N'%tham vấn tâm lý cá nhân%') )  )   )  AND BI.AASTATUS <> 1  AND BI.CUSTOMERID = 'DHHUE'  AND  BI.MATERIALTYPE IN (N'b') AND  BIBLIOGRAPHIC.RECORDSTATUS ='c' "
    }
  ]
